class Solution {
    int prec(char op) {
        if (op == '+' || op == '-') return 1;
        if (op == '*' || op == '/') return 2;
        return 0;
    }
    void reduce(stack<char>& ops, stack<Node*>& nodes) {
        char op = ops.top(); ops.pop();
        Node* r = nodes.top(); nodes.pop();
        Node* l = nodes.top(); nodes.pop();
        nodes.push(new Node(op, l, r));
    }
public:
    Node* expTree(string s) {
        stack<char> ops;
        stack<Node*> nodes;
        for (char ch : s) {
            if (isdigit(ch)) {
                nodes.push(new Node(ch));
            } else if (ch == '(') {
                ops.push(ch);
            } else if (ch == ')') {
                while (!ops.empty() && ops.top() != '(') {
                    reduce(ops, nodes);
                }
                ops.pop();
            } else {
                while (!ops.empty() && prec(ops.top()) >= prec(ch)) {
                    reduce(ops, nodes);
                }
                ops.push(ch);
            }
        }
        while (!ops.empty()) reduce(ops, nodes);
        return nodes.top();
    }
};

class Solution {
    private int prec(char op) {
        if (op == '+' || op == '-') return 1;
        if (op == '*' || op == '/') return 2;
        return 0;
    }
    private void reduce(Deque<Character> ops, Deque<Node> nodes) {
        char op = ops.pop();
        Node r = nodes.pop();
        Node l = nodes.pop();
        nodes.push(new Node(op, l, r));
    }
    public Node expTree(String s) {
        Deque<Character> ops = new ArrayDeque<>();
        Deque<Node> nodes = new ArrayDeque<>();
        for (char ch : s.toCharArray()) {
            if (Character.isDigit(ch)) {
                nodes.push(new Node(ch));
            } else if (ch == '(') {
                ops.push(ch);
            } else if (ch == ')') {
                while (!ops.isEmpty() && ops.peek() != '(') {
                    reduce(ops, nodes);
                }
                ops.pop();
            } else {
                while (!ops.isEmpty() && prec(ops.peek()) >= prec(ch)) {
                    reduce(ops, nodes);
                }
                ops.push(ch);
            }
        }
        while (!ops.isEmpty()) reduce(ops, nodes);
        return nodes.peek();
    }
}

var expTree = function(s) {
    const ops = [];
    const nodes = [];
    const prec = { '+': 1, '-': 1, '*': 2, '/': 2 };
    function reduce() {
        const op = ops.pop();
        const r = nodes.pop();
        const l = nodes.pop();
        nodes.push(new Node(op, l, r));
    }
    for (const ch of s) {
        if (ch >= '0' && ch <= '9') {
            nodes.push(new Node(ch));
        } else if (ch === '(') {
            ops.push(ch);
        } else if (ch === ')') {
            while (ops.length > 0 && ops[ops.length - 1] !== '(') {
                reduce();
            }
            ops.pop();
        } else {
            while (ops.length > 0 && prec[ops[ops.length - 1]] >= prec[ch]) {
                reduce();
            }
            ops.push(ch);
        }
    }
    while (ops.length > 0) reduce();
    return nodes[0];
};
